(()=>{'use strict';
const button=document.getElementById('circlePreviewButton');if(!button)return;const PROFILE='safariCircleProfile',POSTS='safariCirclePosts',BACKUP='safariCirclePreviewBackup';
function samplePosts(){const now=Date.now();return [{id:'circle-preview-field-note',author:'Amara Field Notes',role:'Safari photographer',type:'photograph',species:'African wildlife',country:'Botswana',place:'',locationProtected:true,text:'A field note about patience, light and respecting the distance between observer and animal.',visibility:'public',image:'',liked:false,comments:[{author:'Kito Guide',text:'Field ethics make the photograph stronger.',createdAt:new Date(now-1200000).toISOString()}],createdAt:new Date(now-600000).toISOString()},{id:'circle-preview-question',author:'Kito Guide',role:'Guide',type:'question',species:'Birding',country:'Kenya',place:'',locationProtected:true,text:'What details do you record first when an unfamiliar bird appears only briefly?',visibility:'public',image:'',liked:true,comments:[],createdAt:new Date(now-3600000).toISOString()}]}
function restore(reload=true){try{const backup=JSON.parse(sessionStorage.getItem(BACKUP)||'{}');backup.profile===null?localStorage.removeItem(PROFILE):localStorage.setItem(PROFILE,backup.profile);backup.posts===null?localStorage.removeItem(POSTS):localStorage.setItem(POSTS,backup.posts)}catch{localStorage.removeItem(PROFILE);localStorage.removeItem(POSTS)}sessionStorage.removeItem(BACKUP);if(reload)location.reload()}
function decorate(){const compose=document.getElementById('circlePostForm');compose.hidden=true;document.getElementById('circlePreviewBanner')?.remove();compose.insertAdjacentHTML('afterend','<div class="circle-preview-banner" id="circlePreviewBanner"><strong>Circle interface preview</strong><span>Explore every community section. Create an account when you are ready to participate.</span><button type="button" data-circle-join>Join Circle</button></div>');const aside=document.getElementById('circleProfile');if(!document.getElementById('circleExitPreview'))aside.insertAdjacentHTML('beforeend','<button type="button" class="circle-exit-preview" id="circleExitPreview">Exit preview</button>');document.getElementById('circleExitPreview').addEventListener('click',()=>restore());document.querySelector('[data-circle-join]').addEventListener('click',()=>{restore(false);document.getElementById('circleCreateTab').click()});document.getElementById('circleEditProfile').disabled=true;document.getElementById('circleDeleteData').hidden=true}
button.addEventListener('click',()=>{sessionStorage.setItem(BACKUP,JSON.stringify({profile:localStorage.getItem(PROFILE),posts:localStorage.getItem(POSTS)}));const preview={id:'preview',name:'Safari Explorer',handle:'explore_circle',role:'Safari traveller',home:'Africa',bio:'Exploring the Safari Circle community experience.',verified:false,preview:true,createdAt:new Date().toISOString()};localStorage.setItem(PROFILE,JSON.stringify(preview));localStorage.setItem(POSTS,JSON.stringify(samplePosts()));window.circleShowProfile?.(preview);decorate();document.querySelector('[data-circle-tab="feed"]')?.click()});
if(sessionStorage.getItem(BACKUP)&&JSON.parse(localStorage.getItem(PROFILE)||'null')?.preview)decorate();
})();
